const backends = {
  darwin: require('./macosKeychain'),
  linux: require('./linuxSecretService'),
  win32: require('./windowsCredentialManager')
}

function native (options = {}) {
  function getSync (publicKey) {
    const env = options.processEnv || process.env
    const backend = backends[process.platform]
    if (!backend || env.CI || env.DOTENVX_NO_NATIVE === 'true' || options.noNative === true || options.native === false) return {}
    try {
      const value = backend.get(publicKey)
      return value ? { [publicKey]: value } : {}
    } catch {
      // Preserve CLI fallback: unresolved keys are reported by the parser.
      return {}
    }
  }
  // Native stores retain their existing blocking implementation in both paths.
  return { get: async publicKey => getSync(publicKey), getSync }
}

module.exports = native
